-- platform-migration:model_defaults_physical: 35 model defaults in 13 relations made physical (generated by `manage.py ue_model_defaults_sql`).
-- A Django model that gives a column a default writes it on every INSERT, and the column had none, so a row written by any other writer failed (NOT NULL) or stored something else.
-- No Drizzle declaration names these relations: the model's default is the relation's own design, and the database takes it over unchanged. Every value below is the one the model already writes.
-- Rows that exist keep what they hold. A column that already has a default keeps it; a column that already carries a comment is refused, because the rollback finds what this migration set by its tag.
DO $defaults$
DECLARE
  r record;
  target regclass;
  column_number smallint;
  current_default text;
BEGIN
  FOR r IN
    SELECT * FROM (VALUES
    ('public', 'audit_logs', 'audit_id', 'gen_random_uuid()'),
    ('public', 'compliance_snapshots', 'created_by', '''system'''),
    ('public', 'compliance_snapshots', 'metadata', '''{}''::jsonb'),
    ('public', 'compliance_snapshots', 'previous_hash', ''''''),
    ('public', 'compliance_snapshots', 'sequence_number', '0'),
    ('public', 'domain_events', 'correlation_id', ''''''),
    ('public', 'domain_events', 'created_at', 'now()'),
    ('public', 'domain_events', 'metadata', '''{}''::jsonb'),
    ('public', 'domain_events', 'payload', '''{}''::jsonb'),
    ('public', 'evidence_artifacts', 'size_bytes', '0'),
    ('public', 'evidence_packs', 'artifact_count', '0'),
    ('public', 'evidence_packs', 'checksum_manifest', '''{}''::jsonb'),
    ('public', 'evidence_packs', 'description', ''''''),
    ('public', 'evidence_packs', 'metadata', '''{}''::jsonb'),
    ('public', 'evidence_packs', 'pack_hash', ''''''),
    ('public', 'evidence_packs', 'requested_by', ''''''),
    ('public', 'evidence_packs', 'sealed_by', ''''''),
    ('public', 'evidence_packs', 'status', '''draft'''),
    ('public', 'evidence_packs', 'total_size_bytes', '0'),
    ('public', 'failed_login_attempts', 'attempt_id', 'gen_random_uuid()'),
    ('public', 'federation_memberships', 'status', '''active'''),
    ('public', 'integration_registry', 'consecutive_failures', '0'),
    ('public', 'integration_registry', 'endpoint_url', ''''''),
    ('public', 'integration_registry', 'failure_count', '0'),
    ('public', 'integration_registry', 'last_failure_reason', ''''''),
    ('public', 'integration_registry', 'max_retries', '5'),
    ('public', 'integration_registry', 'metadata', '''{}''::jsonb'),
    ('public', 'integration_registry', 'retry_policy', '''exponential_backoff'''),
    ('public', 'integration_registry', 'secret', ''''''),
    ('public', 'integration_registry', 'status', '''active'''),
    ('public', 'oauth_providers', 'provider_id', 'gen_random_uuid()'),
    ('public', 'organization_users', 'organization_user_id', 'gen_random_uuid()'),
    ('public', 'pack_download_log', 'log_id', 'gen_random_uuid()'),
    ('public', 'pack_verification_log', 'verification_id', 'gen_random_uuid()'),
    ('public', 'rate_limit_events', 'event_id', 'gen_random_uuid()')
    ) AS v(schema_name, table_name, column_name, default_sql)
    ORDER BY schema_name, table_name, column_name
  LOOP
    target := to_regclass(format('%I.%I', r.schema_name, r.table_name));
    IF target IS NULL THEN
      RAISE EXCEPTION 'platform model defaults fail-closed: %.% does not exist.', r.schema_name, r.table_name;
    END IF;
    SELECT a.attnum, pg_get_expr(d.adbin, d.adrelid) INTO column_number, current_default
      FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
     WHERE a.attrelid = target AND a.attname = r.column_name AND a.attnum > 0 AND NOT a.attisdropped;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'platform model defaults fail-closed: %.%.% does not exist.', r.schema_name, r.table_name, r.column_name;
    END IF;
    IF current_default IS NOT NULL THEN
      CONTINUE;
    END IF;
    IF col_description(target, column_number) IS NOT NULL THEN
      RAISE EXCEPTION 'platform model defaults fail-closed: %.%.% already carries a comment, so the rollback could not tell what this migration set.', r.schema_name, r.table_name, r.column_name;
    END IF;
    EXECUTE format('ALTER TABLE %I.%I ALTER COLUMN %I SET DEFAULT %s', r.schema_name, r.table_name, r.column_name, r.default_sql);
    EXECUTE format('COMMENT ON COLUMN %I.%I.%I IS %L', r.schema_name, r.table_name, r.column_name, 'platform-migration:model_defaults_physical:default');
  END LOOP;
END
$defaults$;
